if (face->info().processed) return;
face->info().processed = true;

Triangulation::Vertex_handle v = face->vertex(edge);
vertices.push_back(v);

Triangulation::Face_handle neighbor = face->neighbor(edge);
if (neighbor != nullptr && neighbor->info().interior) {
    int neighbor_edge = neighbor->index_of_face(face);
    get_boundary_vertices(neighbor, neighbor_edge, vertices);
} else {
    int next_edge = (edge + 1) % 3;
    get_boundary_vertices(face, next_edge, vertices);
}

